function desktopHeaderNavigation(){const path=(location.hash.slice(1)||'home').split('?')[0];const current=path.startsWith('car/')||path==='compare'?'cars':path.startsWith('brand/')?'brands':path;return `<nav class="desktop-navigation" aria-label="Desktop navigation">${[['home','Home'],['cars','Vehicles'],['brands','Brands'],['process','How It Works'],['more','More']].map(([route,label])=>`<a href="#${route}" class="${current===route?'active':''}" ${current===route?'aria-current="page"':''}>${label}</a>`).join('')}</nav><a class="desktop-book-visit" href="#appointment">Book a Visit ${icon('arrow-up-right')}</a>`}
function desktopBookingPreview(){return `<aside class="booking-desktop-preview">${picture(selected.image,selected.name)}<div><span>Your selected vehicle</span><h2>${esc(selected.name)}</h2><p>Take a closer look, discuss your questions, and plan your next step with the showroom.</p><a href="#car/${selected.id}">View Vehicle Details ${icon('arrow-right')}</a></div></aside>`}
